class AsciiTable {
  constructor(name) {
    this.name = name;
    this.rows = [];
  }

  setHeading(...values) {
    this.heading = values;
    return this;
  }

  addRow(...values) {
    this.rows.push(values);
    return this;
  }

  toString() {
    return [this.name, ...(this.heading ? [this.heading.join(' | ')] : []), ...this.rows.map((r) => r.join(' | '))].join('\n');
  }
}

module.exports = AsciiTable;
